import copy
import os
import pprint
import re

standards = ['ngap', 'xnap', 'e1ap', 'f1ap', 'x2ap', 's1ap', 'm3ap']
STD_PATH = os.path.sep.join([os.path.dirname(__file__), 'standards'])
OUT_PATH = os.path.sep.join([os.path.dirname(__file__), 'flow_definition.py'])
proc_regexp = re.compile(r'(\S+)\s+\w+AP-ELEMENTARY-PROCEDURE\s::=\s*{\s*(\S.*?)\s*PROCEDURE\sCODE',
                         re.MULTILINE | re.DOTALL)
ap_standard_type_names = {'initiating': 'INITIATING MESSAGE',
                          'success': 'SUCCESSFUL OUTCOME',
                          'failure': 'UNSUCCESSFUL OUTCOME'}
fail_procedure_suffix = 'Failure'


protocols_flows = {}


for standard in standards:
    std_filepath = os.path.sep.join([STD_PATH, '{}.txt'.format(standard)])
    with open(std_filepath) as f:
        std_content = f.read()
    standard_upper = str(standard).upper()
    protocols_flows[standard_upper] = {}
    procedures = proc_regexp.findall(std_content)
    pprint.pprint(procedures)
    for (procedure, messages) in procedures:
        messages_list = messages.split('\n')
        success_procedure = []
        fail_procedure = []
        for message in messages_list:
            if ap_standard_type_names['initiating'] in message:
                init_msg = str(message.replace(ap_standard_type_names['initiating'], '')).strip()
                success_procedure.append(init_msg)
                fail_procedure.append(init_msg)
            if ap_standard_type_names['success'] in message and ap_standard_type_names['failure'] not in message:
                succ_msg = str(message.replace(ap_standard_type_names['success'], '')).strip()
                success_procedure.append(succ_msg)
            if ap_standard_type_names['failure'] in message:
                fail_msg = str(message.replace(ap_standard_type_names['failure'], '')).strip()
                fail_procedure.append(fail_msg)
        protocols_flows[standard_upper][procedure] = copy.deepcopy(success_procedure)
        if len(fail_procedure) > 1:
            fail_procedure_name = "{}{}".format(procedure, fail_procedure_suffix)
            protocols_flows[standard_upper][fail_procedure_name] = copy.deepcopy(fail_procedure)
    # pprint.pprint(protocols_flows)

print('Writing new version to file: {}'.format(OUT_PATH))
with open(OUT_PATH, 'w') as f:
    struct_print = pprint.pformat(protocols_flows)[1:-1]
    f.write('{} = {{\n {}\n}}\n'.format('protocols_flows', struct_print))
